PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS admins (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'ADMIN' CHECK(role IN ('SUPER_ADMIN','ADMIN','DISTRIBUTOR','SUPPORT')), status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')), created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), last_login_at TEXT);
CREATE TABLE IF NOT EXISTS admin_sessions (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), admin_id TEXT NOT NULL REFERENCES admins(id), session_token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked_at TEXT, ip_address TEXT, user_agent TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), customer_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, contact_number TEXT, email TEXT COLLATE NOCASE, address TEXT, notes TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')), created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS license_plans (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), name TEXT NOT NULL UNIQUE COLLATE NOCASE, description TEXT NOT NULL DEFAULT '', max_devices INTEGER NOT NULL CHECK(max_devices > 0), duration_days INTEGER NOT NULL CHECK(duration_days > 0), offline_grace_days INTEGER NOT NULL DEFAULT 7 CHECK(offline_grace_days >= 0), status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')), created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS licenses (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), reference TEXT NOT NULL UNIQUE, key_hash TEXT NOT NULL UNIQUE, customer_id TEXT NOT NULL REFERENCES customers(id), plan_id TEXT NOT NULL REFERENCES license_plans(id), status TEXT NOT NULL DEFAULT 'UNUSED' CHECK(status IN ('UNUSED','ACTIVE','EXPIRED','REVOKED','SUSPENDED')), max_devices INTEGER NOT NULL CHECK(max_devices > 0), created_at TEXT NOT NULL DEFAULT (datetime('now')), activated_at TEXT, expires_at TEXT NOT NULL, revoked_at TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), license_id TEXT NOT NULL REFERENCES licenses(id), device_identifier_hash TEXT NOT NULL, device_label TEXT, app_version TEXT, platform_version TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','REPLACED','REVOKED','INACTIVE')), activated_at TEXT NOT NULL DEFAULT (datetime('now')), last_validation_at TEXT, replaced_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_device ON devices(license_id, device_identifier_hash) WHERE status = 'ACTIVE';
CREATE TABLE IF NOT EXISTS license_activations (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), license_id TEXT NOT NULL REFERENCES licenses(id), device_id TEXT REFERENCES devices(id), event TEXT NOT NULL, app_version TEXT, platform_version TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS license_validations (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), license_id TEXT REFERENCES licenses(id), device_id TEXT REFERENCES devices(id), valid INTEGER NOT NULL CHECK(valid IN (0,1)), status TEXT NOT NULL, app_version TEXT, platform_version TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS license_renewals (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), license_id TEXT NOT NULL REFERENCES licenses(id), admin_id TEXT REFERENCES admins(id), previous_expires_at TEXT NOT NULL, new_expires_at TEXT NOT NULL, duration_days INTEGER NOT NULL, notes TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS mobile_sessions (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), license_id TEXT NOT NULL REFERENCES licenses(id), device_id TEXT NOT NULL REFERENCES devices(id), credential_hash TEXT NOT NULL UNIQUE, issued_at TEXT NOT NULL DEFAULT (datetime('now')), expires_at TEXT, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))), admin_id TEXT REFERENCES admins(id), action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', ip_address TEXT, user_agent TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS system_settings (setting_key TEXT PRIMARY KEY, setting_value TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_licenses_status ON licenses(status); CREATE INDEX IF NOT EXISTS idx_licenses_expiration ON licenses(expires_at); CREATE INDEX IF NOT EXISTS idx_devices_license ON devices(license_id); CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);
INSERT OR IGNORE INTO license_plans(name,description,max_devices,duration_days,offline_grace_days) VALUES ('INDIVIDUAL','Single-device access for independent operators.',1,365,7),('PROFESSIONAL','Access for professional operators.',3,365,7),('CREW','Shared access for a working crew.',8,365,14);
INSERT OR IGNORE INTO system_settings(setting_key,setting_value) VALUES ('default_offline_grace_days','7'),('mobile_api_version','v1');
